package main

import (
	"log"
	"net/http"
	"time"
)

// booksExportPrefix is the bucket-relative directory of a stored catalogue
// export. The rest of the key is generated by the server, so two exports never
// share a key.
const booksExportPrefix = "exports/books/"

// exportS3Response is the body of a 201 stored catalogue export. URL is a
// presigned GET and ExpiresAt is the RFC 3339 UTC instant, at second precision,
// it stops working at, so the presigned URL is the only place a signature ever
// reaches the browser.
type exportS3Response struct {
	Key       string `json:"key"`
	URL       string `json:"url"`
	ExpiresAt string `json:"expiresAt"`
	Size      int64  `json:"size"`
}

// exportBooksToS3 renders the whole catalogue as books.csv, stores it under a
// server-generated key and answers with a short-lived presigned GET for it. The
// CSV comes from renderBooksCSV, so the object carries the same header, quoting
// and CRLF line endings as GET /books/export. The bytes are rendered into a
// buffer before the single Put, so a failure leaves no partial object. A nil
// storage leaves the route answering 503, so the service still boots without an
// object-store configuration.
func exportBooksToS3(store *BookStore, storage objectStorage, now func() time.Time) http.HandlerFunc {
	if now == nil {
		now = time.Now
	}

	return func(w http.ResponseWriter, r *http.Request) {
		if storage == nil {
			writeStorageFailure(w, errStorageNotConfigured)
			return
		}

		body, err := renderBooksCSV(store.List())
		if err != nil {
			log.Printf("catalog books export to s3: rendering the catalogue: %v", err)
			writeStorageFailure(w, errStorageUnavailable)
			return
		}

		key, err := newObjectKey(booksExportPrefix)
		if err != nil {
			log.Printf("catalog books export to s3: %v", err)
			writeStorageFailure(w, errStorageUnavailable)
			return
		}

		if err := storage.Put(r.Context(), key, body, csvContentType); err != nil {
			log.Printf("catalog books export to s3: storing %q: %v", key, err)
			writeStorageFailure(w, errStorageUnavailable)
			return
		}

		ttl := presignLifetime(storage)
		url, err := storage.PresignGet(r.Context(), key, ttl)
		if err != nil {
			log.Printf("catalog books export to s3: presigning %q: %v", key, err)
			writeStorageFailure(w, errStorageUnavailable)
			return
		}

		writeJSON(w, http.StatusCreated, exportS3Response{
			Key:       key,
			URL:       url,
			ExpiresAt: now().Add(ttl).UTC().Truncate(time.Second).Format(time.RFC3339),
			Size:      int64(len(body)),
		})
	}
}
